SourceCode.Declaration:
/// <summary>
/// Extension of ReqItemTable form
/// </summary>
[ExtensionOf(formStr(ReqItemTable))]
final class METReqItemTableForm_Extension
{
}

Method.Source:
/// <summary>
/// Initializes form.
/// </summary>
public void init()
{
    next init();

    ReqItemTable_ds.object(fieldNum(ReqItemTable, METIntercompanySourcedWarehouse))
                   .registerOverrideMethod(methodStr(FormDataObject, lookup),
                                          formMethodStr(ReqItemTable, metIntercompanySourcedWarehouseLookup),
                                          this);
}

/// <summary>
/// Set form control method is called from active method to get current value
/// </summary>
public void setFormControls()
{
    next setFormControls();

    FormRun formRun = this as FormRun;

    FormDataSource formDatasource = formRun.dataSource(tableStr(ReqItemTable));
    ReqItemTable reqItemTable = formDatasource.cursor();

    FormGroupControl formGroupControl = formRun.design().controlName(formControlStr(ReqItemTable, METIntercompanySourced));

    formGroupControl.optionValue(reqItemTable.METInterCompanySourced);        

}

/// <summary>
/// Enable disable fields
/// </summary>
void enableFields()
{
    FormRun formRun = this as FormRun;

    FormDataSource formDatasource = formRun.dataSource(tableStr(ReqItemTable));
    ReqItemTable reqItemTable = formDatasource.cursor();
    FormGroupControl formGroupControl = formRun.design().controlName(formControlStr(ReqItemTable, METIntercompanySourced));

    next enableFields();

    formDatasource.object(fieldnum(ReqItemTable, METInterCompanySourced)).allowEdit(reqItemTable.ReqPOType == ReqPOType::Purch ? true : false);
    formDatasource.object(fieldNum(ReqItemTable, METIntercompanySourcedWarehouse)).allowEdit((reqItemTable.ReqPOType == ReqPOType::Purch && reqItemTable.METInterCompanySourced == NoYes::Yes));
    formGroupControl.allowEdit(reqItemTable.ReqPOType == ReqPOType::Purch ? true : false);
    formGroupControl.enabled(reqItemTable.ReqPOType == ReqPOType::Purch ? true : false);
}

/// <summary>
/// Constructs lookup for <c>METIntercompanySourcedWarehouse</c> field.
/// </summary>
/// <param name = "_control">
/// <c>FormStringControl</c>.
/// </param>
public void metIntercompanySourcedWarehouseLookup(FormStringControl _control)
{
    InventParameters inventParameters = InventParameters::find();

    Query query = new Query();
    QueryBuildDataSource queryBuildDataSource;
    QueryBuildRange queryBuildRange;

    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation), _control);

    sysTableLookup.addLookupField(fieldNum(InventLocation, InventLocationId));
    sysTableLookup.addLookupField(fieldNum(InventLocation, Name));

    queryBuildDataSource = query.addDataSource(tableNum(InventLocation));

    query.allowCrossCompany(true);
    query.clearCompanyRange();

    if (inventParameters.METInterCompanyPurchaseLegalEntity)
    {
        query.addcompanyRange(inventParameters.METInterCompanyPurchaseLegalEntity);
    }

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
